/* Vegas Poker Planner - shared client
 * Every value rendered here comes from site/data.json, which is generated by
 * scripts/data_source.py from official venue and property pages only.
 */
'use strict';

const NAV = [
  ['index.html', 'Overview', '▦'],
  ['tournaments.html', 'Tournaments', '♠'],
  ['search.html', 'Search all tables', '⌕'],
  ['venues.html', 'Venues', '◈'],
  ['schedule.html', 'Day plan', '◷'],
  ['hotels.html', 'Hotels', '⌂'],
  ['calculator.html', 'Trip cost', '∑'],
  ['ranking.html', 'Ranking', '≡'],
  ['questions.html', 'Questions', '?'],
  ['q-and-a.html', 'Q&amp;A worksheet', '⌸'],
  ['suggestions.html', 'Suggestions', '✦'],
  ['flagged.html', 'Flagged for review', '⚑'],
  ['sources.html', 'Sources', '⛓'],
  ['sheets.html', 'Sheet verification', '☰'],
  ['verification.html', 'Verification', '✓'],
];

const PAGE = document.body.dataset.page || 'home';
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (m) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[m]));
const money = (n) => (typeof n === 'number' && isFinite(n) ? '$' + n.toLocaleString('en-US') : '');
const blank = '<span class="muted">Not published / unverified</span>';

let db = null;
let checks = null;

/* ------------------------------------------------------------------ chrome */
function fileName() {
  const p = location.pathname.split('/').pop();
  return (!p || p === '') ? 'index.html' : p;
}
function renderNav() {
  const file = fileName();
  const links = NAV.map(([href, label, icon]) =>
    `<a href="${href}" class="${file === href ? 'active' : ''}"><span class="ico">${icon}</span>${label}</a>`).join('');
  document.querySelectorAll('[data-nav]').forEach((n) => { n.innerHTML = links; });
  document.querySelectorAll('[data-mobile-nav]').forEach((n) => {
    n.innerHTML = NAV.map(([href, label]) =>
      `<a href="${href}" class="${file === href ? 'active' : ''}">${label}</a>`).join('');
  });
  document.querySelectorAll('[data-asof]').forEach((e) => { e.textContent = db ? db.asOf : ''; });
  document.querySelectorAll('[data-search-form]').forEach((f) => {
    const input = f.querySelector('input');
    if (input && !input.value) input.value = new URLSearchParams(location.search).get('q') || '';
    if (f.dataset.searchBound) return;
    f.dataset.searchBound = 'true';
    f.addEventListener('submit', (ev) => {
      ev.preventDefault();
      const q = (input.value || '').trim();
      if (PAGE === 'search') renderSearchResults(q);
      else location.href = 'search.html?q=' + encodeURIComponent(q);
    });
  });
}

/* ------------------------------------------------------------------- utils */
function venueName(id) {
  const v = (db.venues || []).find((x) => x.id === id);
  return v ? v.name : id;
}
function categoryLabel(id) {
  return (db.categories && db.categories[id]) ? db.categories[id].label : id;
}
function sourceChecksFor(urls) {
  const monitored = checks && Array.isArray(checks.urls) ? checks.urls : [];
  return [...new Set((urls || []).filter(Boolean))]
    .map((url) => monitored.find((row) => row.url === url))
    .filter(Boolean);
}
function isBlockedRow(row) {
  return !!(row.botBlocked || row.outcome === 'blocked' || row.outcome === 'redirected');
}
function sourceStatusBadges(urls) {
  const rows = sourceChecksFor(urls);
  const changed = rows.filter((row) => row.changed);
  const blocked = rows.filter((row) => !row.changed && isBlockedRow(row));
  const unavailable = rows.filter((row) => !row.changed && !isBlockedRow(row) &&
    (row.unavailable || row.status === 'unreachable' || /^HTTP [45]/.test(row.status || '')));
  const badges = [];
  if (changed.length) badges.push(`<span class="badge bad" title="${esc(changed.map((r) => `${r.label || r.url}: ${r.checked || ''}`).join('; '))}">Source changed · review</span>`);
  if (blocked.length) badges.push(`<span class="badge info" title="${esc(blocked.map((r) => `${r.label || r.url}: ${r.status || 'blocked'} · ${r.checked || ''}`).join('; '))}">Blocked for the robot, not missing · read by hand</span>`);
  if (unavailable.length) badges.push(`<span class="badge warn" title="${esc(unavailable.map((r) => `${r.label || r.url}: ${r.status || 'unavailable'} · ${r.checked || ''}`).join('; '))}">Source unavailable · recheck</span>`);
  return badges.join(' ');
}
function sourceLinks(e) {
  const out = [];
  if (e.structureUrl) out.push(`<a href="${esc(e.structureUrl)}" target="_blank" rel="noopener">Structure sheet</a>`);
  if (e.scheduleUrl) out.push(`<a href="${esc(e.scheduleUrl)}" target="_blank" rel="noopener">Official schedule</a>`);
  const ruleUrls = Object.values(e.rules || {}).map((rule) => rule && rule.source);
  const badges = sourceStatusBadges([e.structureUrl, e.scheduleUrl, ...ruleUrls]);
  if (badges) out.push(badges);
  return out.join('<span class="muted"> · </span>');
}
function ruleBadge(status) {
  const map = {
    'single-entry-on-sheet': ['warn', 'No extra-entry terms printed · cap unconfirmed'],
    'none-printed': ['ok', 'No re-entry, rebuy or add-on printed'],
    'multiple-entries': ['warn', 'More than one entry possible'],
    'multi-buyin': ['warn', 'More than one entry possible'],
    'separate-flights': ['warn', 'Separate start flights'],
    // The section prints an explicit cap on starting flights, but still permits one re-entry
    // into that flight, so the event is not a one-entry tournament.
    'one-flight-cap': ['warn', 'One entry per flight + one re-entry'],
    'not-verified': ['bad', 'Entry rules not verified'],
    'not-allowed': ['ok', 'Re-entry not allowed'],
    'allowed': ['warn', 'Allowed'],
    'none': ['ok', 'None printed'],
    'paid-chip-gratuity': ['warn', 'Optional paid chip boost'],
    'not-cash-tournament': ['info', 'Seat prizes, not cash'],
    'special-format': ['info', 'Special format'],
    'implied-multiple': ['warn', 'Repeated entries expected'],
    'source-conflict': ['bad', 'Official sources disagree'],
    'partial': ['warn', 'Partly published'],
    'confirmed': ['ok', 'Confirmed'],
  };
  const [cls, label] = map[status] || ['info', status || 'Not stated'];
  return `<span class="badge ${cls}">${esc(label)}</span>`;
}
function entryCheckCell(e) {
  const st = e.rules && e.rules.singleEntry ? e.rules.singleEntry.status : 'not-verified';
  return ruleBadge(st);
}
function hasConfirmedSingleEntryPolicy(e) {
  const rule = e.rules && e.rules.singleEntry;
  return !!(rule && rule.status === 'confirmed' && rule.maxEntries === 1);
}
function ratioCell(e) {
  if (typeof e.ratio !== 'number' || !e.ratio) return blank;
  return `${e.ratio.toFixed(1)}<span class="muted">× published pool ÷ fee</span>`;
}

/* ------------------------------------------------------------- tournaments */
const state = {
  q: '', from: '', to: '', venue: '', category: '', format: '',
  singleOnly: false, candidateOnly: false, walkOnly: false, hotelWalk: 'venetian',
  showUndated: true, showPast: false,
};

// filteredEvents({ ignoreWalk: true }) returns the rows that match every filter except the
// 30-minute walking limit, so the page can say how many rows the limit hides and why.
function filteredEvents(opts) {
  const ignoreWalk = !!(opts && opts.ignoreWalk);
  const q = state.q.trim().toLowerCase();
  return (db.events || []).filter((e) => {
    if (state.singleOnly && !hasConfirmedSingleEntryPolicy(e)) return false;
    if (state.candidateOnly && e.entryType !== 'none') return false;
    if (state.venue && e.venue !== state.venue) return false;
    if (state.category && e.category !== state.category) return false;
    if (state.format && e.format !== state.format) return false;
    if (!state.showUndated && !e.date) return false;
    if (!state.showPast && e.status === 'past') return false;
    if (state.from && e.date && e.date < state.from) return false;
    if (state.to && e.date && e.date > state.to) return false;
    if (state.from && !e.date) return false;
    if (state.to && !e.date) return false;
    if (state.walkOnly && !ignoreWalk) {
      const walk = walkMinutes(state.hotelWalk, e.venue);
      if (walk === null || walk > WALK_LIMIT_MIN) return false;
    }
    if (q) {
      const hay = [e.name, e.venue, venueName(e.venue), e.date, e.time, e.format, e.category,
        e.rules && e.rules.singleEntry ? e.rules.singleEntry.excerpt : ''].join(' ').toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }).sort((a, b) => {
    const da = a.date || '9999-99-99', dbv = b.date || '9999-99-99';
    if (da !== dbv) return da < dbv ? -1 : 1;
    const ta = (a.time || ''), tb = (b.time || '');
    return ta < tb ? -1 : ta > tb ? 1 : 0;
  });
}
const WALK_LIMIT_MIN = 30;   // the brief's limit: a hotel must be within a 30-minute walk of the venue
// The planner's own stated transfer allowance, published in site/data.json planNotes.transfer and
// quoted in the schedule page's method note. Kept here so the same number labels a same-day event.
const TRANSFER_MIN = 30;
// Formats that let a player spend more money for an advantage (rebuy, add-on, multi-buy-in,
// multi-flight). They are never presented as an equal alternative to a single-entry event.
const EXTRA_SPEND_TYPES = new Set(['multi-buyin', 'multi-flight']);
/* "5:10 PM" -> 1030. Returns null for a blank or unparseable time rather than guessing one. */
function minutesFromMidnight(time) {
  const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(String(time || '').trim());
  if (!m) return null;
  let hour = parseInt(m[1], 10) % 12;
  if (m[3].toUpperCase() === 'PM') hour += 12;
  return hour * 60 + parseInt(m[2], 10);
}

function hotelName(id) {
  const h = (db.hotels || []).find((x) => x.id === id);
  return h ? h.name : id;
}

/* Routes are recorded in whichever direction they were measured (hotel -> poker room, or
   hotel -> venue), so look both ways. null means no route was measured for the pair (F32). */
function walkRoute(hotelId, venueId) {
  if (!hotelId || !venueId) return null;
  const list = db.routes || [];
  const direct = list.find((x) => x.hotel === hotelId && x.venue === venueId);
  if (direct) return { route: direct, direction: 'measured' };
  if (hotelId === venueId) return { route: { minutes: 0, note: 'the room is inside this hotel' }, direction: 'same property' };
  const reverse = list.find((x) => x.hotel === venueId && x.venue === hotelId);
  // The reverse of a measured pair is a property-to-property figure, not a re-measurement of this
  // direction, and its far end is the resort address rather than the poker room. Say so (F32).
  return reverse ? { route: reverse, direction: 'reverse of the recorded pair' } : null;
}

function walkMinutes(hotelId, venueId) {
  const w = walkRoute(hotelId, venueId);
  return w ? w.route.minutes : null;
}

function walkCell(hotelId, venueId) {
  const w = walkRoute(hotelId, venueId);
  if (!w) return '<span class="muted">no route measured (F32)</span>';
  const m = w.route.minutes;
  const over = m > WALK_LIMIT_MIN;
  const how = w.direction === 'measured' ? '' : ` · ${esc(w.direction)}`;
  return `<span class="muted"${over ? ' style="color:#b3261e"' : ''}>${m} min walk from ${esc(hotelName(hotelId))}${over ? ' · over the limit' : ''}${how}</span>`;
}

/* Walking minutes from a venue to the Venetian poker room. Routes are recorded
   hotel -> venue, so the pair is (hotel = venue, venue = 'venetian'). The reverse
   pair (Venetian -> venue) is a different walk and must not be shown under a
   "walk to the Venetian" label: Wynn -> Venetian is 13 min, Venetian -> Wynn is 19. */
function walkToVenetian(venue) {
  const r = (db.routes || []).find((x) => x.hotel === venue && x.venue === 'venetian');
  return r ? r.minutes : null;
}
function applyTournamentFilters() {
  const host = document.querySelector('[data-tournament-table]');
  if (!host) return;
  const rows = filteredEvents();
  // What the walking limit hides, counted out loud so a filter never silently drops rows.
  let walkOver = 0, walkUnmeasured = 0;
  if (state.walkOnly) {
    const withoutWalk = filteredEvents({ ignoreWalk: true });
    withoutWalk.forEach((e) => {
      const m = walkMinutes(state.hotelWalk, e.venue);
      if (m === null) walkUnmeasured += 1;
      else if (m > WALK_LIMIT_MIN) walkOver += 1;
    });
  }
  const head = `<thead><tr>
      <th>Date</th><th>Start</th><th>Venue</th><th>Event</th>
      <th>Buy-in</th><th>Guaranteed pool</th><th>Pool ÷ fee</th>
      <th>Format</th><th>Entry check</th><th>Late registration</th><th>Est. end</th><th>Last checked / verified</th><th>Sources</th>
    </tr></thead>`;
  const quick = `<div class="pill-row">
      <a class="pill" href="#" data-quick-from="${esc((db.trip || {}).start || '')}" data-quick-to="${esc((db.trip || {}).end || '')}">Trip window${(db.trip || {}).start ? ' ' + esc(db.trip.start) + ' → ' + esc(db.trip.end) : ''}</a>
      <a class="pill" href="#" data-quick-today="1">Today onward</a>
      <a class="pill" href="#" data-quick-clear="1">Clear dates</a>
      <span class="muted">Showing ${state.from ? esc(state.from) : 'any date'} → ${state.to ? esc(state.to) : 'any date'}.
      A date range hides the recurring room events, because those publish no date.</span>
    </div>`;
  const body = rows.length ? rows.map((e) => `
    <tr class="row-click" data-id="${esc(e.id)}">
      <td>${e.date ? esc(e.date) : '<span class="muted">Recurring</span>'}${e.status === 'past' ? '<span class="muted">Past</span>' : ''}</td>
      <td>${esc(e.time)}</td>
      <td>${esc(venueName(e.venue))}${state.walkOnly ? walkCell(state.hotelWalk, e.venue) : ''}</td>
      <td class="event-name">${esc(e.name)}${e.eligibility ? `<span class="muted">Restricted: ${esc(e.eligibility)}</span>` : ''}${e.note ? `<span class="muted">${esc(e.note)}</span>` : ''}</td>
      <td>${money(e.buyIn) || blank}</td>
      <td>${money(e.guarantee) || blank}${e.guaranteeNote ? `<span class="muted">${esc(e.guaranteeNote)}</span>` : ''}</td>
      <td>${ratioCell(e)}</td>
      <td>${esc(e.format)}${e.category ? `<span class="muted">${esc(categoryLabel(e.category))}</span>` : ''}</td>
      <td>${entryCheckCell(e)}</td>
      <td>${e.lateReg ? esc(e.lateReg) : blank}</td>
      <td>${e.endEstimate ? esc(e.endEstimate) : blank}<span class="muted">Estimate</span></td>
      <td>${e.lastVerified ? esc(e.lastVerified) : blank}${e.lastChecked ? `<span class="muted">values read ${esc(e.lastChecked)}</span>` : ''}</td>
      <td>${sourceLinks(e)}</td>
    </tr>`).join('') : `<tr><td colspan="13" class="empty">${state.singleOnly ? 'No event in this reviewed data set has a written one-entry-per-player confirmation. See flagged item F31; do not treat the candidate list as strict eligibility.' : 'No rows match the current filters.'}</td></tr>`;
  const walkNote = state.walkOnly
    ? ` Walking limit (${WALK_LIMIT_MIN} min from ${esc(hotelName(state.hotelWalk))}) hides ${walkOver + walkUnmeasured} further rows: ${walkOver} measured over the limit, ${walkUnmeasured} with no measured route (F32).`
    : '';
  host.innerHTML = `${quick}<div class="table-wrap"><table>${head}<tbody>${body}</tbody></table></div>
    <p class="toolbar-note">${rows.length} of ${(db.events || []).length} rows.${walkNote}
    Every row links the official page or PDF it came from. Blank cells are values no official source published.</p>`;
  host.querySelectorAll('[data-quick-from]').forEach((a) => a.addEventListener('click', (ev) => {
    ev.preventDefault();
    state.from = a.dataset.quickFrom;
    state.to = a.dataset.quickTo;
    buildTournamentControls();
    applyTournamentFilters();
  }));
  host.querySelectorAll('[data-quick-today]').forEach((a) => a.addEventListener('click', (ev) => {
    ev.preventDefault();
    state.from = db.today || db.asOf || '';
    state.to = '';
    buildTournamentControls();
    applyTournamentFilters();
  }));
  host.querySelectorAll('[data-quick-clear]').forEach((a) => a.addEventListener('click', (ev) => {
    ev.preventDefault();
    state.from = ''; state.to = '';
    buildTournamentControls();
    applyTournamentFilters();
  }));
  host.querySelectorAll('tr.row-click').forEach((tr) => {
    tr.addEventListener('click', () => showDetail(tr.dataset.id));
  });
  const count = document.querySelector('[data-filtered-count]');
  if (count) count.textContent = rows.length;
}
function showDetail(id) {
  const e = (db.events || []).find((x) => x.id === id);
  const box = document.querySelector('[data-detail]');
  if (!e || !box) return;
  const rules = ['singleEntry', 'reEntry', 'addOn', 'rebuy', 'fee'].filter((k) => e.rules && e.rules[k]);
  box.innerHTML = `
    <div class="detail-head">
      <div>
        <div class="kicker">${esc(venueName(e.venue))} · ${e.date ? esc(e.date) : 'recurring'} · ${esc(e.time)}</div>
        <h3>${esc(e.name)}</h3>
      </div>
      <button class="btn" data-close-detail>Close</button>
    </div>
    <div class="detail-grid">
      <div><span class="label">Entry fee</span><span class="value">${money(e.buyIn) || 'Not published'}</span></div>
      <div><span class="label">Guaranteed pool</span><span class="value">${money(e.guarantee) || 'Not published'}</span></div>
      <div><span class="label">Pool ÷ fee (descriptive)</span><span class="value">${ratioCell(e)}</span></div>
      <div><span class="label">Starting chips</span><span class="value">${e.chips ? esc(e.chips.toLocaleString ? e.chips.toLocaleString('en-US') : e.chips) : 'Not published'}</span></div>
      <div><span class="label">Level length</span><span class="value">${e.levelMin ? esc(e.levelMin) + ' minutes' : 'Not published'}</span></div>
      <div><span class="label">Late registration</span><span class="value">${e.lateReg ? esc(e.lateReg) : 'Not published'}</span></div>
      <div><span class="label">Estimated finish</span><span class="value">${e.endEstimate ? esc(e.endEstimate) + ' (estimate)' : 'Not published'}</span></div>
      <div><span class="label">Format</span><span class="value">${esc(e.format)}</span></div>
      <div><span class="label">Last verified live</span><span class="value">${e.lastVerified ? esc(e.lastVerified) : 'not re-checked'}</span></div>
      <div><span class="label">Values first read</span><span class="value">${e.lastChecked ? esc(e.lastChecked) : '—'}</span></div>
    </div>
    <table class="rules">
      <thead><tr><th>Rule</th><th>Status</th><th>What the official source prints</th><th>Source</th></tr></thead>
      <tbody>${rules.map((k) => {
        const r = e.rules[k];
        return `<tr><td>${esc(k === 'singleEntry' ? 'Single entry' : k === 'reEntry' ? 'Re-entry' : k === 'addOn' ? 'Add-on' : k === 'rebuy' ? 'Rebuy' : 'Fee breakdown')}</td>
          <td>${ruleBadge(r.status)}</td>
          <td class="excerpt">${esc(r.excerpt)}</td>
          <td><a href="${esc(r.source)}" target="_blank" rel="noopener">Official source</a>
              <span class="muted">Retrieved ${esc(r.retrieved || db.asOf)}</span></td></tr>`;
      }).join('')}</tbody>
    </table>
    ${e.note ? `<p class="detail-note">${esc(e.note)}</p>` : ''}
    ${e.eligibility ? `<p class="detail-note warn">Eligibility restriction: ${esc(e.eligibility)}</p>` : ''}
    <p class="detail-note">${sourceLinks(e)}</p>`;
  box.hidden = false;
  box.scrollIntoView({ behavior: 'smooth', block: 'start' });
  box.querySelector('[data-close-detail]').addEventListener('click', () => { box.hidden = true; });
}
function buildTournamentControls() {
  const host = document.querySelector('[data-filters]');
  if (!host) return;
  const venues = (db.venues || []).map((v) => `<option value="${esc(v.id)}">${esc(v.name)}</option>`).join('');
  const cats = Object.keys(db.categories || {}).map((k) =>
    `<option value="${esc(k)}">${esc(db.categories[k].label)}</option>`).join('');
  const formats = [...new Set((db.events || []).map((e) => e.format))].sort()
    .map((f) => `<option value="${esc(f)}">${esc(f)}</option>`).join('');
  const hotels = (db.hotels || []).map((h) => `<option value="${esc(h.id)}">${esc(h.name)}</option>`).join('');
  host.innerHTML = `
    <div class="filters">
      <label>Search<input type="search" data-f="q" value="${esc(state.q)}" placeholder="event, venue, rule text…"></label>
      <label>From<input type="date" data-f="from" value="${esc(state.from)}"></label>
      <label>To<input type="date" data-f="to" value="${esc(state.to)}"></label>
      <label>Venue<select data-f="venue"><option value="">All venues</option>${venues}</select></label>
      <label>Category<select data-f="category"><option value="">All categories</option>${cats}</select></label>
      <label>Format<select data-f="format"><option value="">All formats</option>${formats}</select></label>
      <label class="check"><input type="checkbox" data-f="singleOnly"> Single-entry / freezeout confirmed (written max one entry)</label>
      <label class="check"><input type="checkbox" data-f="candidateOnly"> Sheet-screened candidates (entry cap unconfirmed)</label>
      <label class="check"><input type="checkbox" data-f="walkOnly"> Walking limit only
        <select data-f="hotelWalk" aria-label="Hotel the walk is measured from">${hotels}</select>
        <span class="muted">within ${WALK_LIMIT_MIN} min walk</span></label>
      <label class="check"><input type="checkbox" data-f="showUndated" checked> Include recurring rooms</label>
      <label class="check"><input type="checkbox" data-f="showPast"> Include past events (before ${esc(db.today || db.asOf)})</label>
      <button class="btn" data-reset>Reset</button>
    </div>`;
  host.querySelectorAll('[data-f]').forEach((el) => {
    const key = el.dataset.f;
    if (el.type === 'checkbox') el.checked = !!state[key];
    if (el.tagName === 'SELECT') el.value = state[key] || '';
    el.addEventListener(el.tagName === 'SELECT' || el.type === 'date' ? 'change' : 'input', () => {
      state[key] = el.type === 'checkbox' ? el.checked : el.value;
      applyTournamentFilters();
    });
  });
  host.querySelector('[data-reset]').addEventListener('click', () => {
    state.q = ''; state.from = ''; state.to = ''; state.venue = ''; state.category = '';
    state.format = ''; state.singleOnly = false; state.candidateOnly = false; state.walkOnly = false;
    state.hotelWalk = 'venetian'; state.showUndated = true; state.showPast = false;
    buildTournamentControls();
    applyTournamentFilters();
  });
  const q = new URLSearchParams(location.search).get('q');
  if (q) { state.q = q; host.querySelector('[data-f="q"]').value = q; }
}

/* ------------------------------------------------------------------ venues */
const DETAIL_PAGES = { venetian: 'venues/venetian.html', wynn: 'venues/wynn.html',
  bellagio: 'venues/others.html', mgm: 'venues/others.html', caesars: 'venues/others.html',
  horseshoe: 'venues/others.html', aria: 'venues/others.html' };
function detailPage(id) { return DETAIL_PAGES[id] || ''; }

function renderVenueIndex() {
  const host = document.querySelector('[data-venue-list]');
  if (!host) return;
  host.innerHTML = (db.venues || []).map((v) => {
    const evs = (db.events || []).filter((e) => e.venue === v.id);
    const dated = evs.filter((e) => e.date);
    const single = dated.filter((e) => e.entryType === 'none');
    const hotels = (v.hotels || []).map((h) => (db.hotels || []).find((x) => x.id === h)).filter(Boolean);
    const walk = walkToVenetian(v.id);
    return `<article class="card venue-card">
      <div class="venue-top">
        <div>
          <h3>${esc(v.name)}</h3>
          <p class="muted">${esc(v.pokerRoom)}</p>
        </div>
        <span class="pill">${dated.length} dated rows · ${single.length} sheet-screened candidates</span>
      </div>
      <p>${esc(v.series)}</p>
      <p class="muted">${esc(v.note)}</p>
      <p class="venue-meta">
        <span>Walk to the Venetian poker room: <strong>${walk === null ? 'not measured' : walk + ' min'}</strong></span>
        <span>Hotels on this page: <strong>${hotels.length ? hotels.map((h) => esc(h.name)).join(', ') : 'none verified'}</strong></span>
      </p>
      <p><a class="card-link" href="browse.html?view=venue&key=${esc(v.id)}">Events and hotels for ${esc(v.name)} →</a>
         ${detailPage(v.id) ? ` · <a class="card-link" href="${detailPage(v.id)}">Full venue page →</a>` : ''}
         · <a class="card-link" href="${esc(v.page)}" target="_blank" rel="noopener">Official poker page →</a></p>
    </article>`;
  }).join('');
}
function renderStripRooms() {
  const host = document.querySelector('[data-strip-rooms]');
  if (!host) return;
  const rows = (db.stripRooms || []).map((r) => `<tr>
      <td class="event-name">${esc(r.name)}</td>
      <td>${esc(r.status)}</td>
      <td>${esc(r.statusBasis)}</td>
      <td>${esc(r.read)}</td>
      <td>${r.inFeed ? 'Yes' : 'No'}${r.flag ? ` <span class="muted">(${esc(r.flag)})</span>` : ''}</td>
      <td>${r.official ? `<a href="${esc(r.official)}" target="_blank" rel="noopener">Official page</a>` : '<span class="muted">No official page retrieved</span>'}</td>
    </tr>`).join('');
  host.innerHTML = `<table><thead><tr><th>Room</th><th>Status</th><th>Basis</th><th>Read on</th>
    <th>In morning feed</th><th>Official page</th></tr></thead><tbody>${rows}</tbody></table>`;
}
function renderBrowse() {
  const params = new URLSearchParams(location.search);
  const view = params.get('view') || 'venue';
  const key = params.get('key') || 'venetian';
  const head = document.querySelector('[data-browse-head]');
  const body = document.querySelector('[data-browse-body]');
  if (!head || !body) return;
  if (view === 'venue') {
    const v = (db.venues || []).find((x) => x.id === key) || db.venues[0];
    const evs = (db.events || []).filter((e) => e.venue === v.id)
      .sort((a, b) => (a.date || '9999') < (b.date || '9999') ? -1 : 1);
    const hotels = (v.hotels || []).map((h) => (db.hotels || []).find((x) => x.id === h)).filter(Boolean);
    head.innerHTML = `<div class="kicker">Venue page</div><h1>${esc(v.name)}</h1>
      <p>${esc(v.pokerRoom)}</p>
      <p class="muted">${esc(v.series)} · ${esc(v.note)}</p>
      <p><a class="card-link" href="${esc(v.page)}" target="_blank" rel="noopener">Official poker room page →</a>
         · <a class="card-link" href="${esc(v.schedule)}" target="_blank" rel="noopener">Official schedule →</a></p>`;
    body.innerHTML = `
      <section class="section"><h2>Hotels at this property</h2>${hotelCards(hotels)}</section>
      <section class="section"><h2>Published events (${evs.length})</h2>${eventTable(evs)}</section>`;
  } else {
    const cat = db.categories[key] || { label: key, blurb: '' };
    const evs = (db.events || []).filter((e) => e.category === key);
    head.innerHTML = `<div class="kicker">Category page</div><h1>${esc(cat.label)}</h1><p>${esc(cat.blurb)}</p>
      <p class="muted">${evs.length} published rows in this category.</p>`;
    const venues = [...new Set(evs.map((e) => e.venue))].map((id) =>
      `<a class="pill" href="browse.html?view=venue&key=${esc(id)}">${esc(venueName(id))}</a>`).join(' ');
    body.innerHTML = `<section class="section"><p class="pill-row">${venues}</p></section>
      <section class="section"><h2>Rows (${evs.length})</h2>${eventTable(evs)}</section>`;
  }
}
function eventTable(evs) {
  if (!evs.length) return '<div class="empty"><strong>No rows.</strong> Nothing in this view is published in the reviewed sources.</div>';
  const body = evs.map((e) => `
    <tr>
      <td>${e.date ? esc(e.date) : '<span class="muted">Recurring</span>'}</td>
      <td>${esc(e.time)}</td>
      <td class="event-name">${esc(e.name)}</td>
      <td>${money(e.buyIn) || blank}</td>
      <td>${money(e.guarantee) || blank}</td>
      <td>${esc(e.format)}</td>
      <td>${entryCheckCell(e)}</td>
      <td>${esc(e.lastChecked || 'Not recorded')}</td>
      <td>${sourceLinks(e)}</td>
    </tr>`).join('');
  return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Start</th><th>Event</th><th>Buy-in</th>
    <th>Guaranteed pool</th><th>Format</th><th>Entry check</th><th>Last checked</th><th>Sources</th></tr></thead><tbody>${body}</tbody></table></div>`;
}
function hotelCards(hotels) {
  if (!hotels.length) return '<div class="empty"><strong>No hotel row.</strong> No lodging at this property is verified in this pass.</div>';
  return `<div class="cards">${hotels.map((h) => `<article class="card">
    <h3>${esc(h.name)}</h3>
    <p class="muted">${esc(h.rooms || 'Room inventory not published in this pass')}</p>
    <p><strong>Published base rate:</strong> ${h.publishedStartingRates ? '$' + h.publishedStartingRates : 'not published'}</p>
    <p><strong>Mandatory resort fee:</strong> ${h.resortFee ? '$' + h.resortFee + ' plus tax' : 'not verified'}</p>
    <p><strong>True cost per night:</strong> ${h.trueNightlyLow ? '$' + h.trueNightlyLow.toFixed(2) + ' – $' + h.trueNightlyHigh.toFixed(2)
      : (h.derivedNightlyLow ? '$' + h.derivedNightlyLow.toFixed(2) + ' – $' + h.derivedNightlyHigh.toFixed(2) + ' (derived)'
      : 'cannot be computed without a published rate')}</p>
    ${h.derivedNightlyNote ? `<p class="muted">${esc(h.derivedNightlyNote)}</p>` : ''}
    <p><strong>Cancellation deadline:</strong> ${esc(h.cancellation || 'not published')}</p>
    <p><strong>Last checked:</strong> ${esc(h.lastChecked || 'Not recorded')}</p>
    <p class="muted">${esc(h.status || '')}</p>
    <p><a class="card-link" href="${esc(h.source)}" target="_blank" rel="noopener">Official source →</a> ${sourceStatusBadges([h.source, h.feeSource, h.taxSource])}</p>
  </article>`).join('')}</div>`;
}

/* ------------------------------------------------------------------ hotels */
function renderHotels() {
  const host = document.querySelector('[data-hotel-table]');
  if (host) {
    const body = (db.hotels || []).map((h) => {
      const walk = (db.routes || []).filter((r) => r.hotel === h.id && r.venue === 'venetian')[0];
      const self = (db.routes || []).filter((r) => r.hotel === h.id && r.venue === h.id)[0];
      return `<tr>
        <td class="event-name">${esc(h.name)}<span class="muted">${esc(h.rooms || '')}</span></td>
        <td>${esc(h.venue)}</td>
        <td>${h.baseRateFloor ? '$' + h.baseRateFloor + ' – $' + h.baseRateCeiling + '<span class="muted">published starting rates, not date-specific</span>' : blank}</td>
        <td>${h.resortFee ? '$' + h.resortFee + ' plus tax' : blank}</td>
        <td>${h.taxRate ? h.taxRate + '%' : (h.taxReference
          ? `percentage not published<span class="muted">${esc(h.taxReference)} Reference: <a href="${esc(h.taxReferenceSource)}" target="_blank" rel="noopener">room-tax schedule</a></span>`
          : 'percentage not published')}${h.printedFeeAndTax
            ? `<span class="muted">its own page prints $${h.printedFeeAndTax.fee} + $${h.printedFeeAndTax.tax} tax = ${h.printedFeeAndTax.taxPctImplied}%
                ${h.printedFeeAndTax.agreesWithModelTaxPct ? 'agrees with' : 'disagrees with'} the 13.38% the cost model applies ·
                <a href="${esc(h.printedFeeAndTax.source)}" target="_blank" rel="noopener">printed ${esc(h.printedFeeAndTax.excerpt)}</a></span>`
            : ''}</td>
        <td>${h.trueNightlyLow ? '$' + h.trueNightlyLow.toFixed(2) + ' – $' + h.trueNightlyHigh.toFixed(2) + '<span class="muted">floor computed from published components</span>'
          : (h.derivedNightlyLow ? '$' + h.derivedNightlyLow.toFixed(2) + ' – $' + h.derivedNightlyHigh.toFixed(2) +
            '<span class="muted">derived from the property\'s own dated average, fee included, plus 13.38% tax</span>'
            : blank)}</td>
        <td>${esc(h.parking || 'Not published')}</td>
        <td>${esc(h.cancellation || 'Not published')}${h.cancellationDetail ? `<span class="muted">${esc(h.cancellationDetail)}</span>` : ''}${h.checkInOut ? `<span class="muted">${esc(h.checkInOut)}</span>` : ''}</td>
        <td>${esc(h.qualityNote || '')}</td>
        <td>${self && self.minutes !== 0 ? esc(self.minutes) + ' min to the room' : 'room on site'}${walk ? `<span class="muted">${walk.minutes} min to the Venetian</span>` : ''}</td>
        <td>${esc(h.lastVerified || '')}<span class="muted">values read ${esc(h.lastChecked || '')}</span></td>
        <td><a href="${esc(h.source)}" target="_blank" rel="noopener">Room source</a>
            ${h.feeSource ? `<span class="muted"><a href="${esc(h.feeSource)}" target="_blank" rel="noopener">Fee terms</a></span>` : ''}
            ${h.taxSource ? `<span class="muted"><a href="${esc(h.taxSource)}" target="_blank" rel="noopener">Tax terms</a></span>` : ''}
            ${sourceStatusBadges([h.source, h.feeSource, h.taxSource])}</td>
      </tr>`;
    }).join('');
    host.innerHTML = `<div class="table-wrap"><table><thead><tr>
      <th>Property</th><th>Poker room</th><th>Published base rate</th><th>Mandatory resort fee</th><th>Tax</th>
      <th>True cost per night</th><th>Parking</th><th>Cancellation deadline</th><th>Quality evidence</th>
      <th>Walking</th><th>Last verified</th><th>Sources</th></tr></thead><tbody>${body}</tbody></table></div>`;
  }
  const bookingHost = document.querySelector('[data-booking]');
  if (bookingHost) {
    const rows = (db.bookingLinks || []).map((b) => `<tr>
      <td class="event-name">${esc(b.property)}<span class="muted">${esc(b.stay)}</span></td>
      <td><a href="${esc(b.url)}" target="_blank" rel="noopener">Official booking page for these dates</a>
          <span class="muted">Page read ${esc(b.checkedOn)}</span></td>
      <td>${esc(b.priceInStaticPage)}</td>
      <td><a href="${esc(b.feeSource)}" target="_blank" rel="noopener">Resort-fee terms</a></td></tr>`).join('');
    bookingHost.innerHTML = rows ? `<div class="table-wrap"><table><thead><tr><th>Property and stay</th>
      <th>Official booking link for the dates</th><th>Price read from the page</th><th>Fee terms</th></tr></thead>
      <tbody>${rows}</tbody></table></div>` : '';
  }
  const log = document.querySelector('[data-rate-log]');
  if (log) {
    const money0 = (n) => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    // A multi-night quote is shown night by night, and its all-in per-night figure is the printed
    // checkout total divided by the number of nights. The printed room rates alone are not the
    // cost of a night: the mandatory resort fee and tax are added to them, and the site never
    // publishes a nightly figure it cannot derive from a printed amount.
    const quoteNights = (r) => {
      const nights = Number(r.nights) || (r.nightlyRates || []).length;
      const rates = (r.nightlyRates || []).map(Number);
      if (!nights || rates.length !== nights) return '';
      const total = Number(r.total);
      const allIn = total ? total / nights : null;
      return `<div class="muted">Printed room rates per night: ${rates.map(money0).join(' · ')}</div>` +
        `<div>All-in per night: <b>${allIn ? money0(allIn) : 'not derivable'}</b>` +
        `<span class="muted">printed checkout total ${total ? money0(total) : 'blank'} ÷ ${nights} nights; ` +
        `includes the printed resort fee and tax</span></div>`;
    };
    const body = (db.rateLog || []).map((r) => `<tr>
      <td>${esc(r.hotel)}</td><td>${esc(r.observedOn)}</td>
      <td>${r.publishedStartingRates
        ? (/^[\d,.$]/.test(String(r.publishedStartingRates)) ? '$' + r.publishedStartingRates : esc(r.publishedStartingRates))
        : blank}</td>
      <td>${esc(r.resortFee || 'not published')}</td><td>${esc(r.tax || 'not published')}</td>
      <td>${(r.nightlyRates || []).length ? quoteNights(r)
        : (r.quoteType && r.quoteType.indexOf('Dated official checkout total') === 0
          ? `observed nights: $${r.trueNightlyLow} and $${r.trueNightlyHigh}<span class="muted">one dated quote, two nights; not a price range and not a floor</span>`
          : (r.trueNightlyLow ? '$' + r.trueNightlyLow : blank))}</td>
      <td>${esc(r.quoteType)}<span class="muted">${esc(r.note || '')}</span></td>
      <td><a href="${esc(r.source)}" target="_blank" rel="noopener">Official source</a></td></tr>`).join('');
    log.innerHTML = `<div class="table-wrap"><table><thead><tr><th>Property</th><th>Observed</th><th>Published rate</th>
      <th>Resort fee</th><th>Tax</th><th>True nightly floor</th><th>Quote type</th><th>Source</th></tr></thead><tbody>${body}</tbody></table></div>`;
  }
  const routes = document.querySelector('[data-routes]');
  if (routes) {
    const body = (db.routes || []).map((r) => `<tr>
      <td>${esc(r.hotel)}</td><td>${esc(r.venue)}</td>
      <td>${r.minutes === 0 ? 'On site' : r.minutes + ' minutes'}</td>
      <td>${r.miles ? r.miles + ' mile' : ''}</td>
      <td>${esc(r.via || '')}</td><td>${esc(r.note || '')}</td><td>${esc(r.lastChecked || 'Not recorded')}</td>
      <td><a href="${esc(r.mapsUrl)}" target="_blank" rel="noopener">Live Maps route</a>
          <span class="muted"><a href="${esc(r.source)}" target="_blank" rel="noopener">Venue source</a></span></td></tr>`).join('');
    routes.innerHTML = `<div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Walk</th><th>Distance</th>
      <th>Via</th><th>Note</th><th>Last checked</th><th>Sources</th></tr></thead><tbody>${body}</tbody></table></div>`;
  }
  // A dated quote lists one row per night: two for the older stays, seven for the 23-30 Nov trip stay.
  const nightRows = (q) => {
    const nights = q.nightly
      ? q.nightly.map(([date, rate]) => ({ date, rate, resortFee: q.resortFeePerNight }))
      : [q.nightOne, q.nightTwo];
    return nights.map((n, i) => `<div><span class="label">${esc(n.date)}</span><span class="value">$${n.rate.toFixed(2)} + $${n.resortFee.toFixed(2)} resort fee${q.derivedNightly ? ` · $${q.derivedNightly[i].toFixed(2)} all-in` : ''}</span></div>`).join('');
  };
  const quotesHost = document.querySelector('[data-quotes]');
  if (quotesHost) {
    const all = [];
    (db.hotels || []).forEach((h) => (h.quotes || (h.quote ? [h.quote] : [])).forEach((q) => all.push(q)));
    all.sort((a, b) => (a.observedOn < b.observedOn ? 1 : a.observedOn > b.observedOn ? -1 : 0));
    if (!all.length) {
      quotesHost.innerHTML = '<div class="empty"><strong>No dated checkout total.</strong> No property publishes one for the reviewed dates.</div>';
    } else {
      quotesHost.innerHTML = `<div class="cards">${all.map((q) => `
        <article class="card">
          <span class="pill ${q.observedOn === db.asOf ? 'ok' : ''}">Observed ${esc(q.observedOn)}</span>
          <h3>$${q.total.toFixed(2)} for ${esc(q.nights)} nights</h3>
          <div class="detail-grid">
            <div><span class="label">Property and room</span><span class="value">${esc(q.property)}</span></div>
            <div><span class="label">Stay</span><span class="value">${esc(q.checkIn)} → ${esc(q.checkOut)} · ${esc(q.guests)} adults</span></div>
            <div><span class="label">Offer printed</span><span class="value">${esc(q.offer)}</span></div>
            <div><span class="label">Room detail</span><span class="value">${esc(q.suiteDetail)}</span></div>
            ${nightRows(q)}
            <div><span class="label">Taxes printed</span><span class="value">$${q.taxes.toFixed(2)}</span></div>
            <div><span class="label">Average rate printed</span><span class="value">$${q.averageRate.toFixed(2)}</span></div>
          </div>
          <p class="detail-note">${esc(q.note)}</p>
          <p class="detail-note">Derived nightly cost ${q.derivedNightly.map((v) => '$' + v.toFixed(2)).join(', ')}, from (rate + $55) × 1.1338 — total $${q.derivedTotal.toFixed(2)} against the printed $${q.total.toFixed(2)}.</p>
          <p class="detail-note"><a href="${esc(q.source)}" target="_blank" rel="noopener">Open the same official booking link →</a></p>
        </article>`).join('')}</div>`;
    }
  }
  const linksHost = document.querySelector('[data-booking-links]');
  if (linksHost) {
    const rows = [];
    (db.hotels || []).forEach((h) => {
      if (!(h.bookingLinks || []).length) return;
      rows.push(`<p><strong>${esc(h.name)}</strong></p><ul class="list">${
        h.bookingLinks.map((l) => `<li><a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a></li>`).join('')
      }</ul><p class="muted">${esc(h.bookingLinksNote || '')}</p>`);
    });
    linksHost.innerHTML = rows.length
      ? rows.join('')
      : '<div class="empty"><strong>No date-parameterised booking link verified.</strong> Only the official property pages are linked.</div>';
  }
  const noQuoteHost = document.querySelector('[data-no-quote]');
  if (noQuoteHost) {
    const rows = [];
    (db.hotels || []).forEach((h) => (h.noQuoteWindows || []).forEach((w) => rows.push([h, w])));
    noQuoteHost.innerHTML = rows.length
      ? `<div class="table-wrap"><table><thead><tr><th>Property</th><th>Stay window</th><th>Nights</th>
         <th>What the official engine returned</th><th>Link</th></tr></thead><tbody>${
        rows.map(([h, w]) => `<tr><td>${esc(h.name)}</td><td>${esc(w.checkIn)} → ${esc(w.checkOut)}</td>
          <td>${esc(w.nights)}</td><td>${esc(w.result)}</td>
          <td><a href="${esc(w.url)}" target="_blank" rel="noopener">Open it yourself</a></td></tr>`).join('')
      }</tbody></table></div>`
      : '<div class="empty"><strong>Nothing recorded.</strong> Every stay window opened returned a price.</div>';
  }
  const calHost = document.querySelector('[data-calendar]');
  if (calHost) {
    const h = (db.hotels || []).filter((x) => x.calendarObservation)[0];
    if (!h) {
      calHost.innerHTML = '<div class="empty"><strong>No comparison recorded.</strong></div>';
    } else {
      const c = h.calendarObservation;
      const byDate = {};
      c.windowA.cells.forEach(([d, v]) => { byDate[d] = { a: v }; });
      c.windowB.cells.forEach(([d, v]) => { (byDate[d] = byDate[d] || {}).b = v; });
      const body = Object.keys(byDate).sort().map((d) => {
        const cell = (v) => (v === '' || v === undefined ? '<span class="muted">no price</span>'
          : v === 'placeholder' ? '<span class="muted">$XXX placeholder</span>' : '$' + v.toLocaleString());
        const a = byDate[d].a, b = byDate[d].b;
        const same = String(a) === String(b);
        return `<tr><td>${esc(d)}</td><td>${cell(a)}</td><td>${cell(b)}</td>
          <td>${same ? 'agrees' : '<strong>differs</strong>'}</td></tr>`;
      }).join('');
      calHost.innerHTML = `
        <p class="detail-note">The calendar's own footnote: “${esc(c.footnote)}”</p>
        <div class="table-wrap"><table><thead><tr><th>Date</th>
          <th>${esc(c.windowA.label)}</th><th>${esc(c.windowB.label)}</th><th>Cells agree?</th></tr></thead>
          <tbody>${body}</tbody></table></div>
        <p class="detail-note">Read on ${esc(c.observedOn)}. Where the two readings differ, the calendar is quoting a
        different suite for a different query, not a different nightly price for the same room. Nothing on this site uses
        a calendar cell as a rate; only the itemised quote panel above does. See flag F47.</p>
        <p class="detail-note"><a href="${esc(c.windowA.url)}" target="_blank" rel="noopener">First reading</a> ·
        <a href="${esc(c.windowB.url)}" target="_blank" rel="noopener">Second reading</a></p>`;
    }
  }
  const pr = document.querySelector('[data-poker-rate]');
  if (pr && db.trip && db.trip.pokerRateQualification) {
    pr.innerHTML = '<span class="pill">Play requirement</span><p>' + esc(db.trip.pokerRateQualification) + '</p>';
  }

  const calc = document.querySelector('[data-calculator]');
  if (calc) {
    const venetian = (db.hotels || []).find((hotel) => hotel.id === 'venetian') || {};
    const inputValue = (value) => typeof value === 'number' && Number.isFinite(value) && value >= 0 ? String(value) : '';
    const rawNights = db.trip && db.trip.nights;
    const parsedNights = rawNights === null || rawNights === undefined || rawNights === '' ? null : Number(rawNights);
    const defaultNights = Number.isInteger(parsedNights) && parsedNights >= 0 ? String(parsedNights) : '';
    calc.innerHTML = `
      <div class="calc">
        <label>Published room rate<input type="number" id="calc-rate" min="0" value="${esc(inputValue(venetian.baseRateFloor))}" step="0.01"></label>
        <label>Mandatory resort fee<input type="number" id="calc-fee" min="0" value="${esc(inputValue(venetian.resortFee))}" step="0.01"></label>
        <label>Tax rate %<input type="number" id="calc-tax" min="0" value="${esc(inputValue(venetian.taxRate))}" step="0.01"></label>
        <label>Nights<input type="number" id="calc-nights" min="0" value="${esc(defaultNights)}" step="1"></label>
      </div>
      <p class="calc-out" id="calc-out" aria-live="polite"></p>
      <p class="muted">Formula: (room rate + mandatory resort fee) × (1 + tax rate). Blank or invalid values stay unknown; enter 0 explicitly if it is confirmed. This is arithmetic on published components, not a quote.</p>`;
    const update = () => {
      const number = (id, integer = false) => {
        const input = document.getElementById(id);
        if (input.value.trim() === '' || !input.validity.valid) return null;
        const value = Number(input.value);
        return Number.isFinite(value) && value >= 0 && (!integer || Number.isInteger(value)) ? value : null;
      };
      const rate = number('calc-rate');
      const fee = number('calc-fee');
      const tax = number('calc-tax');
      const nights = number('calc-nights', true);
      const output = document.getElementById('calc-out');
      if ([rate, fee, tax].some((value) => value === null)) {
        output.textContent = 'True nightly cost unavailable: enter valid rate, fee and tax values.';
        return;
      }
      const per = Math.round((rate + fee) * (1 + tax / 100) * 100) / 100;
      if (nights === null) {
        output.innerHTML = `<strong>$${per.toFixed(2)}</strong> per night · stay total unavailable: enter a valid night count.`;
        return;
      }
      output.innerHTML =
        `<strong>$${per.toFixed(2)}</strong> per night · <strong>$${(per * nights).toFixed(2)}</strong> for ${nights} nights`;
    };
    calc.querySelectorAll('input').forEach((i) => i.addEventListener('input', update));
    update();
  }
}

/* ---------------------------------------------------------------- schedule */
function renderSchedule() {
  const host = document.querySelector('[data-plan]');
  if (!host) return;
  const trip = db.trip || {};
  const byId = {};
  (db.events || []).forEach((e) => { byId[e.id] = e; });
  const plan = db.dayPlan || [];
  const conflictsByDate = {};
  (db.planConflicts || []).forEach((c) => {
    (conflictsByDate[c.date] = conflictsByDate[c.date] || []).push(c);
  });
  host.innerHTML = plan.map((p) => {
    const primary = byId[p.primary];
    const fallback = byId[p.fallback];
    const rec = (p.recurring || []).map((r) => {
      const out = r.walk !== undefined && r.walk > 30;
      /* Order this same-day room event against the primary using the planner's own stated
       * assumptions (six-hour session, 30-minute transfer, both published in planNotes), so a
       * late event is presented as what it is — playable after the primary — instead of sitting
       * in an unordered list where it reads like an impossible parallel sequence. Nothing here
       * is a published finish time: the string says "estimated" every time. */
      const startMin = minutesFromMidnight(r.time);
      const primaryStart = minutesFromMidnight(primary ? primary.time : '');
      const base = (startMin === null || primaryStart === null) ? null
        : startMin < primaryStart
          ? { badge: 'warn', text: 'does not follow the primary · starts first' }
          : (p.primaryEnd && startMin >= minutesFromMidnight(p.primaryEnd) + TRANSFER_MIN)
            ? { badge: 'info', text: 'playable after the primary (estimated, +' + TRANSFER_MIN + ' min transfer)' }
            : (p.primaryEnd ? { badge: 'warn', text: 'may overlap the primary (estimated session)' } : null);
      const spend = EXTRA_SPEND_TYPES.has(r.entryType)
        ? `<span class="badge bad">extra-spend format · ${esc(r.entryType)}</span> ` : '';
      return `<li><span class="badge ${out ? 'bad' : 'info'}">${out ? r.walk + ' min walk — outside the 30-minute limit' : (r.walk === 0 ? 'on site' : r.walk + ' min walk')}</span>
        ${base ? `<span class="badge ${base.badge}">${esc(base.text)}</span> ` : ''}${spend}
        <strong>${esc(r.time)}</strong> ${esc(r.name)} <span class="muted">${esc(venueName(r.venue))}</span>
        ${r.buyIn ? `<span class="muted">Buy-in $${r.buyIn}</span>` : ''}</li>`;
    }).join('');
    const conflicts = (conflictsByDate[p.date] || []).map((c) =>
      `<li><span class="badge bad">Impossible sequence (estimate)</span> ${esc(c.detail)}</li>`).join('');
    return `<article class="day">
      <div class="day-head">
        <div><span class="kicker">${esc(p.weekday)}</span><h3>${esc(p.date)}</h3></div>
        <div class="day-badges">${p.candidates} provisional candidate${p.candidates === 1 ? '' : 's'} · entry cap unconfirmed</div>
      </div>
      <div class="day-grid">
        <div class="day-primary">
          <span class="pill warn">Primary candidate · conditional</span>
          ${primary ? `<h4>${esc(primary.name)}</h4>
            <p class="day-meta">${esc(venueName(primary.venue))} · starts ${esc(primary.time)} · estimated finish ${esc(primary.endEstimate)}
              · ${p.primaryWalk === 0 ? 'room on site' : p.primaryWalk + ' min walk'}</p>
            <p class="day-meta">Buy-in <strong>${money(primary.buyIn)}</strong> · guaranteed pool <strong>${money(primary.guarantee)}</strong>
              · pool ÷ fee <strong>${primary.ratio ? primary.ratio.toFixed(1) + '×' : 'not published'}</strong> (descriptive, not a forecast)</p>
            ${p.primaryGuaranteeNote ? `<p class="day-meta warn">Pool note: ${esc(p.primaryGuaranteeNote)}.</p>` : ''}
            <p class="day-meta">Starting chips ${primary.chips ? primary.chips.toLocaleString('en-US') : 'not published'}
              · late registration: ${primary.lateReg ? esc(primary.lateReg) : 'not published'}</p>
            ${primary.eligibility ? `<p class="day-meta warn">Restricted: ${esc(primary.eligibility)}</p>` : ''}
            <p class="day-meta ${p.pokerRateSatisfied ? '' : 'warn'}">Poker-rate condition for the night stayed:
              <strong>${p.pokerRateSatisfied ? 'satisfied' : 'not satisfied as planned'}</strong> — ${esc(p.pokerRateBasis || '')}
              <span class="muted">Published condition: ${esc(p.pokerRateCondition || '')}</span></p>
            <p class="day-meta warn">Provisional candidate only: the reviewed sheet does not establish the maximum entries per player. Confirm in writing before registration.</p>
            <p>${sourceLinks(primary)}</p>` : '<p class="muted">No sheet-screened candidate with a published fee and guarantee on this date.</p>'}
        </div>
        <div class="day-fallback">
          <span class="pill warn">${fallback ? 'Conditional fallback' : (p.fallbackAlternativeId ? 'Same-day alternative · not a fallback' : 'Conditional fallback')}</span>
          ${fallback ? `<h4>${esc(fallback.name)}</h4>
            <p class="day-meta">${esc(venueName(fallback.venue))} · starts ${esc(fallback.time)}
              · buy-in ${money(fallback.buyIn) || 'not published'} · guaranteed ${money(fallback.guarantee) || 'not published'}</p>
            ${p.fallbackGuaranteeNote ? `<p class="day-meta warn">Pool note: ${esc(p.fallbackGuaranteeNote)}.</p>` : ''}
            <p class="day-meta">${esc(p.fallbackReason)}</p>
            ${p.fallbackSequenceNote ? `<p class="day-meta ${p.fallbackSequence === 'replaces' ? 'warn' : ''}"><span class="badge ${p.fallbackSequence === 'replaces' ? 'bad' : 'info'}">${p.fallbackSequence === 'replaces' ? 'replaces the primary' : p.fallbackSequence === 'after' ? 'playable after the primary' : 'timing not compared'}</span> ${esc(p.fallbackSequenceNote)}</p>` : ''}
            <p>${sourceLinks(fallback)}</p>` : `<p class="muted">${esc(p.fallbackReason)}</p>`}
          <ul class="recurring">${rec}</ul>
        </div>
      </div>
      ${conflicts ? `<div class="day-conflicts"><span class="pill danger">Flagged impossible sequences</span><ul>${conflicts}</ul></div>` : ''}
    </article>`;
  }).join('');
  const sum = document.querySelector('[data-plan-summary]');
  if (sum) {
    const t = db.trip || {};
    const nightlyBudgetText = typeof t.nightlyBudget === 'number' && Number.isFinite(t.nightlyBudget) && t.nightlyBudget >= 0
      ? '$' + t.nightlyBudget.toFixed(2) : 'Not published';
    sum.innerHTML = `
      <div class="detail-grid">
        <div><span class="label">Trip dates</span><span class="value">${esc(t.start)} → ${esc(t.end)}</span></div>
        <div><span class="label">Nights</span><span class="value">${esc(t.nights)}</span></div>
        <div><span class="label">Recommended hotel</span><span class="value">The Venetian / The Palazzo resort</span></div>
        <div><span class="label">Nightly budget fixed at</span><span class="value">${esc(nightlyBudgetText)}</span></div>
        <div><span class="label">Primary buy-ins</span><span class="value">${money(t.primaryBuyIns) || 'not computed'}</span></div>
        <div><span class="label">Bankroll with a 25% buffer</span><span class="value">${money(t.bankrollWithBuffer) || 'not computed'}</span></div>
      </div>
      <p class="muted">${esc(t.bankrollNote || '')}</p>`;
  }
  const why = document.querySelector('[data-plan-why]');
  if (why) {
    why.innerHTML = `<ul class="list">${(db.trip.rationale || []).map((r) => `<li>${esc(r)}</li>`).join('')}</ul>
      <p class="muted"><strong>Primary rule.</strong> ${esc(db.planNotes.primaryRule)}</p>
      <p class="muted"><strong>Fallback rule.</strong> ${esc(db.planNotes.fallbackRule)}</p>
      <p class="muted"><strong>${esc(db.sessionLengthAssumption)}</strong></p>`;
  }
}

